with a as(select * from public.authors where open_library_id=any(array['OL185745A','OL234454A','OL200233A','OL27048A','OL22570A','OL7535082A','OL8715660A','OL6972374A','OL15497362A','OL42405A','OL636019A','OL5152952A','OL73094A']::text[]) or id=any(array[3168,1307,669,2606,650,710,668,2995,670,3412]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789023458920','9789464291513','9789056370190','9789056371524','9789060694497','9789024553365','9789025453459','9789083142166','9789025833329','9789038806129','9789462971264','9789023431930']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL13752009W','OL21163827W','OL1736490W','OL1736491W','OL1736492W','OL18157814W','OL24610442W','OL30303220W','OL3793464W','OL43411630W','OL44869785W','OL846581W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['babajagajesnijelajaje','bagajagajesnijelajaje','babajagalegdeeenei','gamechanger','saartjetadema','vrijgevochten','wijzijnwegwerpkinderen','doublehomicide','dubbeledoodslag','fantoommerrie','eenmodernverlangen','hetgeheimvandeklokkenmaker','vanlichtekooienzwiepkanarie','de90steverjaardagvanlouisvanroosgaarde','spergebied']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['babajagajesnijelajaje','bagajagajesnijelajaje','babajagalegdeeenei','gamechanger','saartjetadema','vrijgevochten','wijzijnwegwerpkinderen','doublehomicide','dubbeledoodslag','fantoommerrie','eenmodernverlangen','hetgeheimvandeklokkenmaker','vanlichtekooienzwiepkanarie','de90steverjaardagvanlouisvanroosgaarde','spergebied']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987144001 and 987144999),'editions',(select count(*) from public.editions where id between 987244001 and 987244999),'authors',(select count(*) from public.authors where id between 987344001 and 987344999))) as preflight;
